PageContextMenu = {
	init: function (app, container, page, callback) {
		app = app || session.app;
		container = container || $(".component[name=PageContextMenu]");
		if (!page) { return; }
		$("[name=newChild]", container).off("click").on("click", (e) => PageContextMenu.newChild(e, app, page, callback));
		$("[name=delete]", container).off("click").on("click", (e) => PageContextMenu.destroy(e, page, callback));
		$("[name=properties]", container).off("click").on("click", (e) => PageContextMenu.properties(e, app, page, callback));
		if (callback) {
			$(document).off("click").on("click", callback);
		}
	},

	newChild: function (e, app, page, callback) {
		e.preventDefault();
		var d = new Dialog({ name: "PageContextMenuNewPage", width: 640, height: "auto", title: "[resource_displayname[newpage]]" });
		d.template = $("[name=newChildPageComponent]").first().html();
		d.init(() => PageCreator.init(app, $(".component[name=PageCreator]", $(d.element)), page, callback, d));
	},

	destroy: function (e, page, callback) {
		e.preventDefault();
		var d = new ConfirmDialog({ question: "[resource_description[areyousure]]", confirm: "[resource_displayname[confirm]]", close: "[resource_displayname[close]]" });
		d.events.confirm = async function () {
			await api.destroy("ContentManagement/Page(" +page.Id + ")").then(() => {
				notification.success("[resource_description[PageDeleted]]");
				d.events.close();
				if (callback) { callback("delete"); }
			}).catch((err) => error(err));
		};
		d.init();
	},

	properties: function (e, app, page, callback) {
		e.preventDefault();
		var d = new Dialog();
		d.width = 900;
		d.height = 'auto';
		d.title = "[resource_displayname[pageproperties]]";
		d.template = $("[name=pagePropertiesComponent]").first().html();
		d.init(() => PageProperties.init(app, $(".component[name=PageProperties]", $(d.element)), page, callback));
	}
};
